export const getUpdateAdminSupportUrl = (messageId: number,) => {




  return `/api/admin/support/${messageId}`
}

/**
 * @summary Change support message status
 */
export const updateAdminSupport = async (messageId: number,
    adminSupportUpdate: AdminSupportUpdate, options?: Parameters<typeof customFetch>[1]): Promise<AdminSupportMessage> => {

  return customFetch<AdminSupportMessage>(getUpdateAdminSupportUrl(messageId),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(adminSupportUpdate)
  }
);}





